// Server component - Node.js modules are valid here
// oxlint-disable-next-line eslint-plugin-import(no-nodejs-modules)
import { readFile } from "node:fs/promises";
// oxlint-disable-next-line eslint-plugin-import(no-nodejs-modules)
import { join } from "node:path";

import { codeToHtml } from "shiki";

import { CodeBlock } from "@/components/geistdocs/code-block";
import {
  CodeBlockTab,
  CodeBlockTabs,
  CodeBlockTabsList,
  CodeBlockTabsTrigger,
} from "@/components/geistdocs/code-block-tabs";

interface ElementsInstallerProps {
  path?: string;
}

const loadSourceCode = async (componentPath: string): Promise<string> => {
  try {
    const code = await readFile(
      join(
        process.cwd(),
        "..",
        "..",
        "packages",
        "elements",
        "src",
        `${componentPath}.tsx`
      ),
      "utf8"
    );
    return code
      .replaceAll("@ai-studio/shadcn-ui/", "@/")
      .replaceAll("@ai-studio/", "@/components/ai-elements/");
  } catch (error) {
    console.error(
      `Failed to load component from path: ${componentPath}`,
      error
    );
    return "";
  }
};

const getCommands = (path?: string) => {
  const elementsCommand = path
    ? `npx ai-elements@latest add ${path}`
    : "npx ai-elements@latest";
  const shadcnCommand = path
    ? `npx shadcn@latest add @ai-elements/${path}`
    : "npx shadcn@latest add @ai-elements/all";
  return { elementsCommand, shadcnCommand };
};

interface HighlightedCodePreviewProps {
  highlightedCode: string;
}

const HighlightedCodePreview = ({
  highlightedCode,
}: HighlightedCodePreviewProps) => (
  // oxlint-disable-next-line eslint-plugin-react(no-danger)
  <pre dangerouslySetInnerHTML={{ __html: highlightedCode }} />
);

export const ElementsInstaller = async ({ path }: ElementsInstallerProps) => {
  const sourceCode = path ? await loadSourceCode(path) : "";
  const { elementsCommand, shadcnCommand } = getCommands(path);
  const highlightedCode = await codeToHtml(sourceCode, {
    lang: "tsx",
    themes: { dark: "github-dark", light: "github-light" },
  });

  return (
    <div className="not-prose">
      <CodeBlockTabs defaultValue="ai-elements">
        <CodeBlockTabsList>
          <CodeBlockTabsTrigger value="ai-elements">
            AI Elements
          </CodeBlockTabsTrigger>
          <CodeBlockTabsTrigger value="shadcn">shadcn CLI</CodeBlockTabsTrigger>
          {sourceCode && (
            <CodeBlockTabsTrigger value="manual">Manual</CodeBlockTabsTrigger>
          )}
        </CodeBlockTabsList>
        <CodeBlockTab className="not-prose" value="ai-elements">
          <CodeBlock className="px-4">{elementsCommand}</CodeBlock>
        </CodeBlockTab>
        <CodeBlockTab className="not-prose" value="shadcn">
          <CodeBlock className="px-4">{shadcnCommand}</CodeBlock>
        </CodeBlockTab>
        {sourceCode && (
          <CodeBlockTab className="not-prose" value="manual">
            <CodeBlock className="max-h-[600px] overflow-y-auto">
              <HighlightedCodePreview highlightedCode={highlightedCode} />
            </CodeBlock>
          </CodeBlockTab>
        )}
      </CodeBlockTabs>
    </div>
  );
};

"use client";

import {
  InputGroup,
  InputGroupAddon,
  InputGroupButton,
  InputGroupInput,
  InputGroupText,
} from "@repo/shadcn-ui/components/ui/input-group";
import { track } from "@vercel/analytics";
import { CheckIcon, CopyIcon } from "lucide-react";
import { useState } from "react";
import { toast } from "sonner";

const COPY_TIMEOUT = 2000;

interface InstallerProps {
  command: string;
  className?: string;
}

export const Installer = ({ command, className = "w-48" }: InstallerProps) => {
  const [copied, setCopied] = useState(false);

  const handleCopy = () => {
    navigator.clipboard.writeText(command);
    toast.success("Copied to clipboard");
    setCopied(true);

    track("Copied installer command");
    setTimeout(() => {
      setCopied(false);
    }, COPY_TIMEOUT);
  };

  const Icon = copied ? CheckIcon : CopyIcon;

  return (
    <InputGroup className="h-10 bg-background font-mono shadow-none">
      <InputGroupAddon>
        <InputGroupText className="font-normal text-muted-foreground">
          $
        </InputGroupText>
      </InputGroupAddon>
      <InputGroupInput className={className} readOnly value={command} />
      <InputGroupAddon align="inline-end">
        <InputGroupButton
          aria-label="Copy"
          onClick={handleCopy}
          size="icon-xs"
          title="Copy"
        >
          <Icon className="size-3.5" size={14} />
        </InputGroupButton>
      </InputGroupAddon>
    </InputGroup>
  );
};

"use server";

import { headers } from "next/headers";

import type { Feedback } from "@/components/geistdocs/feedback";

import { siteId } from "@/geistdocs";
import { emotions } from "./emotions";

const protocol = process.env.NODE_ENV === "production" ? "https" : "http";
const baseUrl = `${protocol}://${process.env.NEXT_PUBLIC_VERCEL_PROJECT_PRODUCTION_URL}`;

export const sendFeedback = async (
  url: string,
  feedback: Feedback
): Promise<{ success: boolean }> => {
  const emoji = emotions.find((e) => e.name === feedback.emotion)?.emoji;
  const endpoint = new URL("/feedback", "https://geistdocs.com/feedback");
  const headersList = await headers();

  const response = await fetch(endpoint, {
    body: JSON.stringify({
      emotion: emoji,
      ip: headersList.get("x-real-ip") || headersList.get("x-forwarded-for"),
      label: siteId,
      note: feedback.message,
      ua: headersList.get("user-agent") ?? undefined,
      url: new URL(url, baseUrl).toString(),
    }),
    headers: {
      "Content-Type": "application/json",
    },
    method: "POST",
  });

  if (!response.ok) {
    const error = await response.json();

    console.error(error);

    return { success: false };
  }

  return {
    success: true,
  };
};

export const emotions = [
  {
    emoji: "😭",
    name: "cry",
  },
  {
    emoji: "😕",
    name: "sad",
  },
  {
    emoji: "🙂",
    name: "happy",
  },
  {
    emoji: "🤩",
    name: "amazed",
  },
];

"use client";

import type { SharedProps } from "fumadocs-ui/components/dialog/search";

import { Button } from "@repo/shadcn-ui/components/ui/button";
import { Kbd } from "@repo/shadcn-ui/components/ui/kbd";
import { cn } from "@repo/shadcn-ui/lib/utils";
import { useDocsSearch } from "fumadocs-core/search/client";
import {
  SearchDialog as FumadocsSearchDialog,
  SearchDialogClose,
  SearchDialogContent,
  SearchDialogHeader,
  SearchDialogIcon,
  SearchDialogInput,
  SearchDialogList,
  SearchDialogOverlay,
} from "fumadocs-ui/components/dialog/search";
import { useI18n } from "fumadocs-ui/contexts/i18n";
import { useSearchContext } from "fumadocs-ui/contexts/search";

interface SearchButtonProps {
  className?: string;
  onClick?: () => void;
}

export const SearchDialog = ({
  basePath,
  ...props
}: SharedProps & { basePath: string | undefined }) => {
  const { locale } = useI18n();
  const { search, setSearch, query } = useDocsSearch({
    api: basePath ? `${basePath}/api/search` : "/api/search",
    locale,
    type: "fetch",
  });

  return (
    <FumadocsSearchDialog
      isLoading={query.isLoading}
      onSearchChange={setSearch}
      search={search}
      {...props}
    >
      <SearchDialogOverlay />
      <SearchDialogContent>
        <SearchDialogHeader>
          <SearchDialogIcon />
          <SearchDialogInput />
          <SearchDialogClose />
        </SearchDialogHeader>
        <SearchDialogList items={query.data !== "empty" ? query.data : null} />
      </SearchDialogContent>
    </FumadocsSearchDialog>
  );
};

export const SearchButton = ({ className, onClick }: SearchButtonProps) => {
  const { setOpenSearch } = useSearchContext();

  return (
    <Button
      className={cn(
        "justify-between gap-8 pr-1.5 font-normal text-muted-foreground shadow-none",
        className
      )}
      onClick={() => {
        setOpenSearch(true);
        onClick?.();
      }}
      size="sm"
      type="button"
      variant="outline"
    >
      <span>Search...</span>
      <Kbd className="border bg-background font-medium">⌘K</Kbd>
    </Button>
  );
};

import "@testing-library/jest-dom/vitest";
import { cleanup } from "@testing-library/react";
import failOnConsole from "vitest-fail-on-console";

// Mock clipboard API for browser environment
// oxlint-disable-next-line eslint-plugin-jest(require-hook)
Object.defineProperty(navigator, "clipboard", {
  configurable: true,
  value: {
    // oxlint-disable-next-line eslint-plugin-promise(prefer-await-to-then)
    writeText: vi.fn(() => Promise.resolve()),
  },
  writable: true,
});

// Fail the test if there are any console logs during test execution
// oxlint-disable-next-line eslint-plugin-jest(require-hook)
failOnConsole({
  shouldFailOnAssert: true,
  shouldFailOnDebug: true,
  shouldFailOnError: true,
  shouldFailOnInfo: true,
  shouldFailOnLog: true,
  shouldFailOnWarn: true,
  silenceMessage: (message) => {
    // Silence React 18 deprecation warnings from Radix UI dependencies
    if (message.includes("ReactDOM.render is deprecated since React 18")) {
      return true;
    }
    // Silence Sonner deprecation warnings
    if (message.includes("toastOptions.className")) {
      return true;
    }
    // Silence React act() warnings from Radix UI tooltip timing
    if (message.includes("was not wrapped in act")) {
      return true;
    }
    // Silence Radix UI DialogContent accessibility warnings in tests
    // Tests use aria-describedby="test-description" but don't render the element
    if (message.includes("Missing `Description` or `aria-describedby")) {
      return true;
    }
    return false;
  },
});

// Cleanup after each test - this is a global setup file
// oxlint-disable-next-line eslint-plugin-jest(no-hooks), eslint-plugin-jest(require-top-level-describe)
afterEach(() => {
  cleanup();
  vi.restoreAllMocks();
});

import {
  convertToModelMessages,
  createUIMessageStream,
  createUIMessageStreamResponse,
  stepCountIs,
  streamText,
} from "ai";

import type { MyUIMessage } from "./types";

import { createTools } from "./tools";
import { createSystemPrompt } from "./utils";

export const maxDuration = 800;

interface RequestBody {
  messages: MyUIMessage[];
  currentRoute: string;
  pageContext?: {
    title: string;
    url: string;
    content: string;
  };
}

export async function POST(req: Request) {
  try {
    const { messages, currentRoute, pageContext }: RequestBody =
      await req.json();

    // Filter out UI-only page context messages (they're just visual feedback)
    const actualMessages = messages.filter(
      (msg) => !msg.metadata?.isPageContext
    );

    // If pageContext is provided, prepend it to the last user message
    let processedMessages = actualMessages;

    if (pageContext && actualMessages.length > 0) {
      const lastMessage = actualMessages.at(-1);

      if (!lastMessage) {
        return new Response(
          JSON.stringify({
            error: "No last message found",
          }),
          { status: 500 }
        );
      }

      if (lastMessage.role === "user") {
        // Extract text content from the message parts
        const userQuestion = lastMessage.parts
          .filter((part) => part.type === "text")
          .map((part) => part.text)
          .join("\n");

        processedMessages = [
          ...actualMessages.slice(0, -1),
          {
            ...lastMessage,
            parts: [
              {
                text: `Here's the content from the current page:

**Page:** ${pageContext.title}
**URL:** ${pageContext.url}

---

${pageContext.content}

---

User question: ${userQuestion}`,
                type: "text",
              },
            ],
          },
        ];
      }
    }

    const stream = createUIMessageStream({
      execute: async ({ writer }) => {
        const result = streamText({
          messages: await convertToModelMessages(processedMessages),
          model: "openai/gpt-4.1-mini",
          prepareStep: ({ stepNumber }) => {
            if (stepNumber === 0) {
              return { toolChoice: { toolName: "search_docs", type: "tool" } };
            }
          },
          stopWhen: stepCountIs(10),
          system: createSystemPrompt(currentRoute),
          tools: createTools(writer),
        });

        writer.merge(result.toUIMessageStream());
      },
      originalMessages: messages,
    });

    return createUIMessageStreamResponse({ stream });
  } catch (error) {
    console.error("AI chat API error:", error);

    return new Response(
      JSON.stringify({
        error: "Failed to process chat request. Please try again.",
      }),
      {
        headers: { "Content-Type": "application/json" },
        status: 500,
      }
    );
  }
}

import type { ToolSet, UIMessageStreamWriter } from "ai";

import { tool } from "ai";
import { initAdvancedSearch } from "fumadocs-core/search/server";
import z from "zod";

import { i18n } from "@/lib/geistdocs/i18n";
import { getAllPages, getPageByHref } from "@/lib/geistdocs/source";

const createSearchServer = (lang: string) => {
  const pages = getAllPages(lang);

  return initAdvancedSearch({
    indexes: pages.map((page) => ({
      description: page.data.description,
      id: page.url,
      structuredData: page.data.structuredData,
      title: page.data.title ?? "",
      url: page.url,
    })),
  });
};

const log = (message: string) => {
  console.log(`🤖 [Geistdocs] ${message}`);
};

const search_docs = (writer: UIMessageStreamWriter) =>
  tool({
    description: "Search through documentation content by query",
    execute: async ({ query, lang }) => {
      try {
        log(`Creating search server for language: ${lang}`);

        const searchServer = createSearchServer(lang);

        log(`Searching docs for ${query}`);

        const results = await searchServer.search(query);

        log(`Found ${results.length} results`);

        if (results.length === 0) {
          return `No documentation found for query: "${query}"`;
        }

        log(`Processing ${results.length} results...`);

        const promises = results.map(({ url }) => {
          const segments = url.split("#").at(0)?.split("/") ?? [];

          if (segments.length === 0) {
            log(`🤖 [Geistdocs] No segments found for ${url}, skipping...`);
            return null;
          }

          log(`Getting page for ${url}`);

          const result = getPageByHref(url, { language: lang });

          if (!result?.page) {
            log(`No page found for ${url}`);
            return null;
          }

          const { page } = result;

          log(
            `Found page for ${url}: ${page.data.title}, ${page.data.description}`
          );

          return {
            content: JSON.stringify(page.data.structuredData.contents),
            description: page.data.description,
            slug: page.url,
            title: page.data.title,
          };
        });

        log(`Running ${promises.length} promises...`);

        const promiseResults = await Promise.all(promises);

        log(`${promiseResults.length} promises resolved.`);

        // Collect results, then filter to ensure unique slugs
        const formattedResultsRaw = promiseResults.filter(Boolean) as {
          title: string;
          description: string;
          content: string;
          slug: string;
        }[];

        log(`Formatted ${formattedResultsRaw.length} results.`);

        // Ensure slugs are unique
        const seenSlugs = new Set<string>();
        const formattedResults = formattedResultsRaw.filter((doc) => {
          if (seenSlugs.has(doc.slug)) {
            return false;
          }
          seenSlugs.add(doc.slug);
          return true;
        });

        log(`Filtered ${formattedResults.length} results.`);

        const trimmedResults = formattedResults.slice(0, 8);

        log(`Trimmed ${trimmedResults.length} results.`);

        for (const [index, doc] of trimmedResults.entries()) {
          log(`Writing doc: ${doc.title}, ${doc.slug}`);
          writer.write({
            sourceId: `doc-${index}-${doc.slug}`,
            title: doc.title,
            type: "source-url",
            url: doc.slug,
          });
        }

        const formattedResultsString = trimmedResults
          .map(
            (doc) =>
              `**${doc.title}**\nURL: ${doc.slug}\n${
                doc.description || ""
              }\n\n${doc.content.slice(0, 1500)}${
                doc.content.length > 1500 ? "..." : ""
              }\n\n---\n`
          )
          .join("\n");

        return `Found ${trimmedResults.length} documentation pages for "${query}":\n\n${formattedResultsString}`;
      } catch (error) {
        const message =
          error instanceof Error ? error.message : "Unknown error";

        return `Error processing results: ${message}`;
      }
    },
    inputSchema: z.object({
      lang: z
        .string()
        .describe("The two letter language code of the documentation to search")
        .optional()
        .default(i18n.defaultLanguage),
      query: z.string().describe("Search query to find relevant documentation"),
    }),
  });

const get_doc_page = tool({
  description:
    'Get the full content of a specific documentation page or guide by slug. Use the exact URL path from search results (e.g., "/docs/vercel-blob/client-upload" or "/guides/how-to-build-ai-app")',
  inputSchema: z.object({
    lang: z
      .string()
      .describe("The two letter language code of the documentation to search")
      .optional()
      .default(i18n.defaultLanguage),
    slug: z
      .string()
      .describe("The slug/path of the documentation page or guide to retrieve"),
  }),
  // biome-ignore lint/suspicious/useAwait: "tool calls must be async"
  execute: async ({ slug, lang }) => {
    log(`Getting all pages for language: ${lang}`);
    const pages = getAllPages(lang);

    log(`Getting doc page for ${slug} in language: ${lang}`);
    const doc = pages.find((d) => d.url === slug || d.url.endsWith(slug));

    if (!doc) {
      return `Documentation page not found: "${slug}"`;
    }

    return `# ${doc.data.title}\n\n${
      doc.data.description ? `${doc.data.description}\n\n` : ""
    }${doc.data.structuredData.contents}`;
  },
});

const list_docs = tool({
  description: "Get a list of all available documentation pages",
  inputSchema: z.object({
    lang: z
      .string()
      .describe("The two letter language code of the documentation to search")
      .optional()
      .default(i18n.defaultLanguage),
  }),
  // biome-ignore lint/suspicious/useAwait: "tool calls must be async"
  execute: async ({ lang }) => {
    log(`Getting all pages for language: ${lang}`);
    const pages = getAllPages(lang);

    const docsList = pages
      .map(
        (doc) => `- **${doc.data.title}** (${doc.url}): ${doc.data.description}`
      )
      .join("\n");

    return `Available Documentation Pages (${pages.length} total):\n\n${docsList}`;
  },
});

export const createTools = (writer: UIMessageStreamWriter) =>
  ({
    get_doc_page,
    list_docs,
    search_docs: search_docs(writer),
  }) satisfies ToolSet;

import type { InferUITools, UIMessage } from "ai";

import { z } from "zod/v3";

import type { createTools } from "./tools";

const dataPartsSchema = z.object({
  notification: z.object({
    message: z.string(),
  }),
  "stream-end": z.object({
    message: z.string(),
  }),
});

type MyDataParts = z.infer<typeof dataPartsSchema>;

export type MyTools = InferUITools<ReturnType<typeof createTools>>;

interface MessageMetadata {
  isPageContext?: boolean;
  pageContext?: {
    title: string;
    url: string;
  };
}

export type MyUIMessage = UIMessage<MessageMetadata, MyDataParts, MyTools>;

import type { NextRequest } from "next/server";

import { getAllPages, getLLMText } from "@/lib/geistdocs/source";

export const revalidate = false;

export const GET = async (
  _req: NextRequest,
  { params }: RouteContext<"/[lang]/llms.txt">
) => {
  const { lang } = await params;
  const pages = getAllPages(lang);
  const scan = pages.map((page) => getLLMText(page));
  const scanned = await Promise.all(scan);

  return new Response(scanned.join("\n\n"), {
    headers: {
      "Content-Type": "text/markdown; charset=utf-8",
    },
  });
};

import type { StructuredData } from "fumadocs-core/mdx-plugins/remark-structure";

import { createTokenizer as createTokenizerJapanese } from "@orama/tokenizers/japanese";
import { createTokenizer as createTokenizerMandarin } from "@orama/tokenizers/mandarin";
import { createI18nSearchAPI } from "fumadocs-core/search/server";

import { translations } from "@/geistdocs";
import { i18n } from "@/lib/geistdocs/i18n";
import {
  componentsSource,
  docsSource,
  examplesSource,
} from "@/lib/geistdocs/source";

const localeMap: Record<
  string,
  {
    language?: string;
    components?: {
      tokenizer:
        | ReturnType<typeof createTokenizerMandarin>
        | ReturnType<typeof createTokenizerJapanese>;
    };
    search?: {
      threshold: number;
      tolerance: number;
    };
  }
> = Object.fromEntries(
  Object.entries(translations).map(([locale, translation]) => [
    locale,
    { language: translation.displayName.toLowerCase() },
  ])
);

if ("cn" in translations) {
  localeMap.cn = {
    components: {
      tokenizer: createTokenizerMandarin(),
    },
    search: {
      threshold: 0,
      tolerance: 0,
    },
  };
}

if ("jp" in translations) {
  localeMap.jp = {
    components: {
      tokenizer: createTokenizerJapanese(),
    },
    search: {
      threshold: 0,
      tolerance: 0,
    },
  };
}

const indexes: {
  title: string;
  description: string | undefined;
  structuredData: StructuredData;
  url: string;
  id: string;
  locale: string;
}[] = [];

for (const lang of docsSource.getLanguages()) {
  for (const page of lang.pages) {
    indexes.push({
      description: page.data.description,
      id: page.url,
      locale: lang.language,
      structuredData: page.data.structuredData,
      title: page.data.title,
      url: page.url,
    });
  }
}

for (const lang of componentsSource.getLanguages()) {
  for (const page of lang.pages) {
    indexes.push({
      description: page.data.description,
      id: page.url,
      locale: lang.language,
      structuredData: page.data.structuredData,
      title: page.data.title,
      url: page.url,
    });
  }
}

for (const lang of examplesSource.getLanguages()) {
  for (const page of lang.pages) {
    indexes.push({
      description: page.data.description,
      id: page.url,
      locale: lang.language,
      structuredData: page.data.structuredData,
      title: page.data.title,
      url: page.url,
    });
  }
}

export const { GET } = createI18nSearchAPI("advanced", {
  i18n,
  indexes,
  localeMap,
});

import { notFound } from "next/navigation";

import { generateParams, getLLMText, getPage } from "@/lib/geistdocs/source";

export const revalidate = false;

export async function GET(
  _req: Request,
  { params }: RouteContext<"/[lang]/llms.mdx/[[...slug]]">
) {
  const { slug, lang } = await params;
  const page = getPage(slug, lang);

  if (!page) {
    notFound();
  }

  return new Response(await getLLMText(page), {
    headers: {
      "Content-Type": "text/markdown",
    },
  });
}

export const generateStaticParams = async ({
  params,
}: RouteContext<"/[lang]/llms.mdx/[[...slug]]">) => {
  const { lang } = await params;

  return generateParams(lang);
};

/** biome-ignore-all lint/suspicious/noConsole: "server only" */

import type { NextRequest } from "next/server";
import type { Registry, RegistryItem } from "shadcn/schema";

import { track } from "@vercel/analytics/server";
import { NextResponse } from "next/server";
import { promises as fs, readdirSync } from "node:fs";
import { readFile } from "node:fs/promises";
import { join } from "node:path";
import { Project } from "ts-morph";

const getRegistryUrl = (request: NextRequest) => {
  const host = request.headers.get("host");
  const protocol = host?.includes("localhost") ? "http" : "https";
  return `${protocol}://${host}`;
};

const packageDir = join(process.cwd(), "..", "..", "packages", "elements");
const packagePath = join(packageDir, "package.json");
const packageJson = JSON.parse(await readFile(packagePath, "utf8"));

const examplesDir = join(
  process.cwd(),
  "..",
  "..",
  "packages",
  "examples",
  "src"
);

const internalDependencies = Object.keys(packageJson.dependencies || {}).filter(
  (dep) => dep.startsWith("@repo") && dep !== "@repo/shadcn-ui"
);

const dependenciesSet = new Set(
  Object.keys(packageJson.dependencies || {}).filter(
    (dep) =>
      ![
        "react",
        "react-dom",
        "@repo/shadcn-ui",
        ...internalDependencies,
      ].includes(dep)
  )
);

const devDependenciesSet = new Set(
  Object.keys(packageJson.devDependencies || {}).filter(
    (dep) =>
      ![
        "@repo/typescript-config",
        "@types/react",
        "@types/react-dom",
        "typescript",
      ].includes(dep)
  )
);

// Registry should auto-add ai sdk v5 as a dependency
dependenciesSet.add("ai");
dependenciesSet.add("@ai-sdk/react");
dependenciesSet.add("zod");

const dependencies = new Set(dependenciesSet);
const devDependencies = [...devDependenciesSet];

// Normalize to package root (supports scoped and deep subpath imports)
const getBasePackageName = (specifier: string) => {
  if (specifier.startsWith("@")) {
    const parts = specifier.split("/");
    return parts.slice(0, 2).join("/");
  }
  return specifier.split("/")[0];
};

// Build a mapping from runtime package -> its @types devDependency package(s)
const TYPES_PREFIX = "@types/";
const typesDevDepsMap = new Map<string, string[]>();
for (const devDep of devDependencies) {
  if (devDep.startsWith(TYPES_PREFIX)) {
    const name = devDep.slice(TYPES_PREFIX.length);
    // Scoped packages in DefinitelyTyped use __ separator, e.g. @types/babel__core for @babel/core
    const runtime = name.includes("__") ? name.replace("__", "/") : name;
    const list = typesDevDepsMap.get(runtime) ?? [];
    list.push(devDep);
    typesDevDepsMap.set(runtime, list);
  }
}

const srcDir = join(packageDir, "src");

const packageFiles = readdirSync(srcDir, { withFileTypes: true });
const tsxFiles = packageFiles.filter(
  (file) => file.isFile() && file.name.endsWith(".tsx")
);

const exampleFiles = readdirSync(examplesDir, { withFileTypes: true });
const exampleTsxFiles = exampleFiles.filter(
  (file) => file.isFile() && file.name.endsWith(".tsx")
);

const files: {
  type: string;
  path: string;
  content: string;
}[] = [];

const fileContents = await Promise.all(
  tsxFiles.map(async (tsxFile) => {
    const filePath = join(srcDir, tsxFile.name);
    const content = await fs.readFile(filePath, "utf8");
    const parsedContent = content
      .replaceAll("@repo/shadcn-ui/components/ui/", "@/registry/default/ui/")
      .replaceAll("@repo/shadcn-ui/lib/", "@/lib/");

    return {
      content: parsedContent,
      path: `registry/default/ai-elements/${tsxFile.name}`,
      type: "registry:component",
    };
  })
);

const exampleContents = await Promise.all(
  exampleTsxFiles.map(async (exampleFile) => {
    const filePath = join(examplesDir, exampleFile.name);
    const content = await fs.readFile(filePath, "utf8");
    const parsedContent = content
      .replaceAll("@repo/shadcn-ui/components/ui/", "@/registry/default/ui/")
      .replaceAll("@repo/shadcn-ui/lib/", "@/lib/")
      .replaceAll("@repo/elements/", "@/components/ai-elements/");

    return {
      content: parsedContent,
      path: `registry/default/examples/${exampleFile.name}`,
      type: "registry:block",
    };
  })
);

files.push(...fileContents, ...exampleContents);

const registryDependenciesSet = new Set<string>();

// Extract shadcn/ui components from file content
const shadcnComponents =
  files
    .map((f) => f.content)
    .join("\n")
    .match(/@\/registry\/default\/ui\/([a-z-]+)/g)
    ?.map((path) => path.split("/").pop())
    .filter((name): name is string => Boolean(name)) || [];

// Extract AI element components from file content
const aiElementComponents =
  files
    .map((f) => f.content)
    .join("\n")
    .match(/@\/components\/ai-elements\/([a-z-]+)/g)
    ?.map((path) => path.split("/").pop())
    .filter((name): name is string => Boolean(name)) || [];

// Add shadcn/ui components to set
for (const component of shadcnComponents) {
  registryDependenciesSet.add(component);
}

// Add AI element components to set (these become registry dependencies)
for (const component of aiElementComponents) {
  registryDependenciesSet.add(component);
}

// Create items for the root registry response
const componentItems: RegistryItem[] = tsxFiles.map((componentFile) => {
  const componentName = componentFile.name.replace(".tsx", "");

  const item: RegistryItem = {
    description: `AI-powered ${componentName.replace("-", " ")} component.`,
    files: [
      {
        path: `registry/default/ai-elements/${componentFile.name}`,
        target: `components/ai-elements/${componentFile.name}.tsx`,
        type: "registry:component",
      },
    ],
    name: componentName,
    title: componentName
      .split("-")
      .map((word) => word.charAt(0).toUpperCase() + word.slice(1))
      .join(" "),
    type: "registry:component",
  };

  return item;
});

const exampleItems: RegistryItem[] = exampleTsxFiles.map((exampleFile) => {
  const exampleName = exampleFile.name.replace(".tsx", "");

  const item: RegistryItem = {
    description: `Example implementation of ${exampleName.replace("-", " ")}.`,
    files: [
      {
        path: `registry/default/examples/${exampleFile.name}`,
        target: `components/ai-elements/examples/${exampleFile.name}.tsx`,
        type: "registry:block",
      },
    ],
    name: `example-${exampleName}`,
    title: `${exampleName
      .split("-")
      .map((word) => word.charAt(0).toUpperCase() + word.slice(1))
      .join(" ")} Example`,
    type: "registry:block",
  };

  return item;
});

const items: RegistryItem[] = [...componentItems, ...exampleItems];

const getResponse = (registryUrl: string): Registry => ({
  homepage: new URL("/elements", registryUrl).toString(),
  items,
  name: "ai-elements",
});

interface RequestProps {
  params: Promise<{ component: string }>;
}

// biome-ignore lint/complexity/noExcessiveCognitiveComplexity: Registry route requires handling many component cases
export const GET = async (request: NextRequest, { params }: RequestProps) => {
  const { component } = await params;
  const parsedComponent = component.replace(".json", "");
  const registryUrl = getRegistryUrl(request);
  const response = getResponse(registryUrl);

  if (parsedComponent === "registry") {
    try {
      track("registry:registry");
    } catch (error) {
      console.warn("Failed to track registry:registry:", error);
    }
    return NextResponse.json(response);
  }

  // Handle "all.json" - bundle all components into a single RegistryItem
  if (parsedComponent === "all") {
    try {
      track("registry:all");
    } catch (error) {
      console.warn("Failed to track registry:all:", error);
    }

    // Collect all dependencies and registry dependencies from all components
    const allDependencies = new Set<string>();
    const allDevDependencies = new Set<string>();
    const allRegistryDependencies = new Set<string>();
    const allFiles: RegistryItem["files"] = [];

    // Process each component file
    for (const componentFile of tsxFiles) {
      const file = files.find(
        (f) => f.path === `registry/default/ai-elements/${componentFile.name}`
      );

      if (file) {
        allFiles.push({
          content: file.content,
          path: file.path,
          target: `components/ai-elements/${componentFile.name}`,
          type: file.type as RegistryItem["type"],
        });

        // Parse imports for dependencies
        const project = new Project({ useInMemoryFileSystem: true });
        try {
          const sourceFile = project.createSourceFile(file.path, file.content);
          const imports = sourceFile
            .getImportDeclarations()
            .map((d) => d.getModuleSpecifierValue());

          for (const moduleName of imports) {
            if (!moduleName) {
              continue;
            }

            const pkg = getBasePackageName(moduleName);
            // Check if it's a regular dependency
            if (dependencies.has(pkg)) {
              allDependencies.add(pkg);
              // Check if it has a corresponding @types/ package
              const typePkgs = typesDevDepsMap.get(pkg);
              if (typePkgs) {
                for (const t of typePkgs) {
                  allDevDependencies.add(t);
                }
              }
            }

            // Check if it's a dev dependency
            if (devDependencies.includes(moduleName)) {
              allDevDependencies.add(moduleName);
            }

            // Check if it's a registry dependency (shadcn/ui components)
            if (moduleName.startsWith("@/registry/default/ui/")) {
              const componentName = moduleName.split("/").pop();
              if (componentName) {
                allRegistryDependencies.add(componentName);
              }
            }
          }
        } catch (error) {
          console.warn(`Failed to parse imports for ${file.path}:`, error);
        }
      }
    }

    const allComponentsItem: RegistryItem = {
      $schema: "https://ui.shadcn.com/schema/registry-item.json",
      dependencies: [...allDependencies],
      description: "Bundle containing all AI-powered components.",
      devDependencies: [...allDevDependencies],
      files: allFiles,
      name: "all",
      registryDependencies: [...allRegistryDependencies],
      title: "All AI Elements",
      type: "registry:component",
    };

    return NextResponse.json(allComponentsItem);
  }

  try {
    track(`registry:${parsedComponent}`);
  } catch (error) {
    console.warn(`Failed to track ${parsedComponent}:`, error);
  }

  // Only process the parsedComponent, not an array

  // Find the item for the requested component or example
  const item = response.items.find((i) => i.name === parsedComponent);

  if (!item) {
    return NextResponse.json(
      { error: `Component "${parsedComponent}" not found.` },
      { status: 404 }
    );
  }

  // Find the corresponding file content
  let file: { type: string; path: string; content: string } | undefined;
  if (item.type === "registry:component") {
    file = files.find(
      (f) => f.path === `registry/default/ai-elements/${parsedComponent}.tsx`
    );
  } else if (
    item.type === "registry:block" &&
    parsedComponent.startsWith("example-")
  ) {
    const exampleFileName = `${parsedComponent.replace("example-", "")}.tsx`;
    file = files.find(
      (f) => f.path === `registry/default/examples/${exampleFileName}`
    );
  }

  if (!file) {
    return NextResponse.json(
      { error: `File for "${parsedComponent}" not found.` },
      { status: 404 }
    );
  }

  // Parse imports for the single component to determine actual dependencies
  const usedDependencies = new Set<string>();
  const usedDevDependencies = new Set<string>();
  const usedRegistryDependencies = new Set<string>();

  const project = new Project({ useInMemoryFileSystem: true });

  try {
    const sourceFile = project.createSourceFile(file.path, file.content);
    const imports = sourceFile
      .getImportDeclarations()
      .map((d) => d.getModuleSpecifierValue());

    for (const moduleName of imports) {
      if (!moduleName) {
        continue;
      }

      // Check if it's a relative dependency
      if (moduleName.startsWith("./")) {
        const relativePath = moduleName.split("/").pop();
        if (relativePath) {
          usedRegistryDependencies.add(
            new URL(
              `/api/registry/${relativePath}.json`,
              registryUrl
            ).toString()
          );
        }
      }

      const pkg = getBasePackageName(moduleName);
      // Check if it's a regular dependency
      if (dependencies.has(pkg)) {
        usedDependencies.add(pkg);
        // Check if it has a corresponding @types/ package
        const typePkgs = typesDevDepsMap.get(pkg);
        if (typePkgs) {
          for (const t of typePkgs) {
            usedDevDependencies.add(t);
          }
        }
      }

      // Check if it's a dev dependency (though less common in component files)
      if (devDependencies.includes(moduleName)) {
        usedDevDependencies.add(moduleName);
      }

      // Check if it's a registry dependency (shadcn/ui components)
      if (moduleName.startsWith("@/registry/default/ui/")) {
        const componentName = moduleName.split("/").pop();
        if (componentName) {
          usedRegistryDependencies.add(componentName);
        }
      }

      // Check if it's an AI element dependency
      if (moduleName.startsWith("@/components/ai-elements/")) {
        const componentName = moduleName.split("/").pop();
        if (componentName) {
          usedRegistryDependencies.add(
            new URL(`/${componentName}.json`, registryUrl).toString()
          );
        }
      }
    }
  } catch (error) {
    console.warn(`Failed to parse imports for ${file.path}:`, error);
  }

  // Add internal dependencies for the requested component
  for (const dep of internalDependencies) {
    const packageName = dep.replace("@repo/", "");
    usedRegistryDependencies.add(
      new URL(`/elements/${packageName}.json`, registryUrl).toString()
    );
  }

  const itemResponse: RegistryItem = {
    $schema: "https://ui.shadcn.com/schema/registry-item.json",
    dependencies: [...usedDependencies],
    description: item.description,
    devDependencies: [...usedDevDependencies],
    files: [
      {
        content: file.content,
        path: file.path,
        target: `components/ai-elements/${item.name}.tsx`,
        type: file.type as Exclude<
          RegistryItem["type"],
          "registry:base" | "registry:font"
        >,
      },
    ],
    name: item.name,
    registryDependencies: [...usedRegistryDependencies],
    title: item.title,
    type: item.type as Exclude<
      RegistryItem["type"],
      "registry:base" | "registry:font"
    >,
  };

  return NextResponse.json(itemResponse);
};

